using UnifiedRgb.Core.Color;
using UnifiedRgb.Devices;
using static UnifiedRgb.Core.Effects.EffectMath;

namespace UnifiedRgb.Core.Effects.Generators;

/// <summary>堆叠 Stacking: Dots run to the far end and stack up one by one; the full stack then fades out.</summary>
public sealed class StackingEffect : EffectGenerator
{
    public const string EffectId = "Stacking";

    public StackingEffect()
        : base(EffectId, new EffectParamSchema("Stacking", "堆叠", 1, 7, true, true, EffectMath.One, true))
    {
    }

    public override void Render(in RenderContext ctx, Span<Rgb> output)
    {
        var n = output.Length;
        var cycle = (n * (n + 1L) / 2) + n;
        var s = Floor(ctx.T * ctx.Rate(5.0, 60.0)) % cycle;
        var stacked = n;
        var dot = -1;
        for (var h = 0; h < n; h++)
        {
            var run = n - h;
            if (s < run)
            {
                stacked = h;
                dot = (int)s;
                break;
            }

            s -= run;
        }

        var fade = dot < 0 ? 1f - ((float)s / n) : 1f;
        for (var i = 0; i < n; i++)
        {
            var p = ctx.Index(i);
            if (p >= n - stacked)
            {
                output[i] = Scale(ctx.Color(n - 1 - p), fade);
            }
            else
            {
                output[i] = p == dot ? ctx.Color(stacked) : Rgb.Black;
            }
        }
    }
}
